Given a suitable $1$-periodic potential $W$ which satisfies in particular $W'(k)=0$ for $k\in\hbox{\bf Z}$ ($W$ will be precised later
in assumption \textbf{(A)}), it is known (see Section \ref{subsection-layer}) that there exists a unique solution $\phi$ of
\begin{equation}\label{eq::0}
\left\{\begin{array}{l}
L\phi -W'(\phi)=0 \quad \mbox{on}\quad \hbox{\bf R},\\
\displaystyle{\phi'>0 \quad \mbox{and}\quad \phi(-\infty)=0,\quad \phi(0)=\frac 1 2,\quad \phi(+\infty)=1.}
\end{array}\right.
\end{equation}

The proof of Theorem \ref{th::1} is done by constructing suitable sub and
supersolutions essentially based on the following ansatz of the solution:
\begin{equation}\label{eq::an}
\tilde{v}^\varepsilon(t,x)=\frac{\varepsilon}{\alpha}\sigma(t,x)+\sum_{i=1}^N
\left\{ \phi\left(\frac{x-x_i(t)}{\varepsilon}\right)-\varepsilon
  \dot{x}_i(t)\  \psi\left(\frac{x-x_i(t)}{\varepsilon}\right) \right\}
\end{equation}
where $\psi$ is a suitable corrector.

\label{th::5}{\bf (Existence and properties of the layer solution)}\\
Under assumption Ai), there exists a unique solution $\phi$ of
(\ref{eq::0bis}).
Moreover $\phi \in C^{1,\beta}_{loc}(\hbox{\bf R})$ for some $0<\beta <1$, and there exists a constant $C>0$ such that
\begin{equation}\label{eq::5}
0<\phi'(x)\le \frac{C}{1+x^2}  \quad \mbox{for all}\quad x\in\hbox{\bf R}
\end{equation}
and
\begin{equation}\label{eq::6}
\left|\phi(x)-H(x)+\frac{1}{\alpha \pi x}\right| \quad \le \quad \frac{C}{x^2}   \quad \mbox{for all}\quad |x|\ge 1
\end{equation}
where $H$ is the Heaviside function and $\alpha=W''(0)$.

\label{pro::2}{\bf (Supersolution at the initial time)}\\
Under assumption (A), there exists $\delta_0>0$ such that for all
$0<\delta\le \delta_0$, we have
\begin{equation}\label{eq::8}
\overline{v}^\varepsilon(0,x)\ge v_0^\varepsilon(x) \quad \mbox{for
  all}\quad x\in\hbox{\bf R}
\end{equation}
for $\varepsilon >0$ small enough.

\label{lem::2}{\bf (Computation using the ansatz)}\\
Let
$$\displaystyle{I^\varepsilon := \varepsilon \overline{v}^\varepsilon_t
+\frac{1}{\varepsilon}\left\{W'(\overline{v}^\varepsilon) -\varepsilon
  L\overline{v}^\varepsilon -\varepsilon \sigma\right\}}.$$
Then for any $i_0\in \left\{1,...,N\right\}$, we have
\begin{equation}\label{eq::12}
I^\varepsilon = e^\varepsilon_{i_0} + (\alpha \tilde{\sigma}-\sigma) +
O(\tilde{\phi}_{i_0}) \left\{\eta \overline{c}_{i_0} +\tilde{\sigma} + \sum_{i\not= i_0}
  \frac{\tilde{\phi}_i}{\varepsilon} \right\}
\end{equation}
where $\eta$ is defined in (\ref{eq::7'}) and the error
$e^\varepsilon_{i_0}$ is given by
$$e^\varepsilon_{i_0}= O(\varepsilon) + \sum_{i\not= i_0} O(\psi_i) +
\sum_{i\not= i_0} O(\tilde{\phi}_i) + \sum_{i\not= i_0}
  O\left(\frac{(\tilde{\phi}_i)^2}{\varepsilon}\right).$$

\label{pro::3}{\bf (Supersolution for positive time)}\\
Under assumption (A), there exists $\delta_0>0$ such that for all
$0<\delta\le \delta_0$ and given $T>0$, we have
\begin{equation}\label{eq::9}
\overline{v}^\varepsilon_t \ge \frac{1}{\varepsilon}
\left(L\overline{v}^\varepsilon - \frac{1}{\varepsilon}
W'(\overline{v}^\varepsilon) +\sigma(t,x) \right)   \quad \mbox{on}\quad
(0,T)\times \hbox{\bf R}
\end{equation}
for $\varepsilon >0$ small enough.

Recall that we set $L=-(-\Delta)^{\frac12}$ to be the half-Laplacian operator
defined in Fourier space by
\begin{equation}\label{eq::3}
\widehat{Lw}(\xi):=-|\xi|\widehat{w}(\xi) \quad \mbox{for}\quad \xi\in\hbox{\bf R}.
\end{equation}

\begin{equation}\label{eq::200}\frac{1}{2\pi}\int_{\hbox{\bf R}}d\xi\ |\xi||\widehat{w}(\xi)|^2=<-Lw,w>_{H^{-\frac12}(\hbox{\bf R})\times
  H^{\frac12}(\hbox{\bf R})} = {\frac{1}{2\pi}}
\int_{\hbox{\bf R}\times \hbox{\bf R}} dx dx' \ \frac{|w(x')-w(x)|^2}{|x'-x|^2}.\end{equation}

For $u$ smooth and with compact support, the classical embedding trace inequality reads
\begin{equation}\label{trace-inequality}
\norm{Tu}^2_{\dot{H}^{\frac{1}{2}}(\hbox{\bf R})}:=\int_{\mathbb R\times \mathbb R}dxdx' \ \frac{|Tu(x')-Tu(x)|^2}{|x'-x|^2}\leq 2\pi \int_\Omega \abs{\nabla u}^2\,dxdy.\end{equation}
A proof of the previous inequality can be found in corollary 6.3 in \cite{Alberti-Bouchitte-Seppecher:Phase-transition}.
Then \eqref{trace-mapping} follows by putting together the previous line with \eqref{H12-norm} and \eqref{eq::200}. For a general $u$ the result follows by density, while the equality case is dealt with in Theorem \ref{th::4} below.\\

 \label{defi-weak-solution}{\bf (Weak sub/super/solution)}\\
Let $d$ be a measurable bounded function on $\mathbb R$, and let $g\in L^2(\mathbb R)$.
We say that $w\in H^{\frac{1}{2}}(\mathbb R)$ is a weak supersolution for the equation
\begin{equation}\label{weak-equation}
Lw -d(x)w=g \quad \mbox{ on }\partial\Omega
\end{equation}
if, for $u:=P*_x w$ and
$$B(u,v):=\int_{\Omega}\nabla u\cdot\nabla v+\int_{\partial\Omega} d(x)(Tu)(Tv),$$
we have that
\begin{equation}\label{weak-super-solution}B(u,v)\geq \int_{\partial\Omega} gTv\quad\mbox{for all }v\in H.\end{equation}
Respectively, $w$ is a weak subsolution if
\begin{equation}\label{weak-sub-solution} B(u,v)\leq \int_{\partial\Omega} gTv\quad\mbox{for all }v\in H.\end{equation}
Accordingly, we say that $w$ is a weak solution if it is both a weak sub and supersolution.\\

\label{lemma-equivalence}{\bf (Equivalence of solutions)}\\
Given $w\in L^{\infty}(\mathbb R)\cap \mathcal C^{1,\beta}_{\mbox{loc}}(\mathbb R)$, the following two ways of compuing $Lw$, i.e,
\begin{enumerate}
\item as a Dirichlet to Neumann operator (see section 5.3.1., in particular \eqref{eq::4}-\eqref{eq::55});

\item using the L\'evy-Khintchine formula (see theorem \ref{th::2}),
\end{enumerate}
are equivalent.

If, in addition, $w\in H^{\frac{1}{2}}(\mathbb R)$, then the half-Laplacian definition in term of distributions as given in theorem \ref{th::4} is also equivalent. As a consequence, the notions of viscosity and weak solutions from Definitions \ref{defi::1} and \ref{defi-weak-solution}, respectively, coincide in the smooth case.

{\bf (Known existence and properties of the layer solution)}\label{thm-layer-solutions}\\
Let $f$ be any $\mathcal C^{1,\beta}$ function with $0 < \beta < 1$ and such that $W'= -f$. Then there exists a layer solution $u_W\in \mathcal C^{2,\beta}_{\mbox{loc}}(\overline\Omega)$ of \eqref{Cabre-SolaMorales-layer} if and only if
$$W'(0)=W'(1)=0\quad\mbox{and}\quad W> W(0)=W(1)\quad\mbox{in } (0,1).$$
Moreover,
\begin{enumerate}
\item If $W''(0), W''(1)>0$, then a layer solution of \eqref{Cabre-SolaMorales-layer} is unique up to translations in the $x$ variable, and it satisfies
\begin{equation}\label{derivative-positive}(u_W)_x>0\quad\mbox{in }\overline{\Omega}.\end{equation}
\item We have the estimate
\begin{equation}\label{gradient-bound}\abs{\nabla u_W(x,y)}\leq \frac{C}{1+\abs{(x,y)}}, \quad \mbox{for all }x\in\mathbb R, y\geq 0.\end{equation}
\item Set $\phi(x):=u_W(x,0)$. We have the bounds
\begin{equation}
\label{growth-not-sharp}\abs{\phi(x)-H(x)}\leq \frac{C}{1+\abs{x}} \quad\mbox{for all }x\in\mathbb R,
\end{equation}
\begin{equation}\label{derivative-bound}
\frac{C_1}{1+\abs{x}^2} \leq \phi'(x)\leq \frac{C_2}{1+\abs{x}^2},\quad \mbox{for all }x\in\mathbb R,
\end{equation}
for some positive constants $C,C_1,C_2$.
\item A layer solution is always a stable solution. This means that
\begin{equation}\label{stable-solution}\int_{\Omega}\abs{\nabla v}^2+\int_{\partial\Omega}W''(\phi)v^2\geq 0\end{equation}
for every function $v\in\mathcal C^1(\overline{\Omega})$ with compact support in $\overline{\Omega}$.\\
\end{enumerate}

\label{properties}{\bf (Properties of $\phi'$)}. For $\bar u$ defined as $\bar u=P*_x \phi'$, we have that
\begin{enumerate}
\item $\bar u\in H$.
\item $\phi'$ is a weak solution of $Lw-W''(\phi)w=0$ in the sense of Definition \ref{defi-weak-solution}, i.e.,
\begin{equation}\label{eq::907}
B(\bar u,v)=0 \quad \mbox{for all } v\in H.
\end{equation}
    \end{enumerate}

\label{lema-comparison}
Let $v$ be a bounded function in $\Omega$,  $v\in\mathcal C^2(\Omega)$ and $\mathcal C^1$ up to the boundary $\partial\Omega$,  satisfying
\begin{equation}\label{equation-max-principle}
\left\{\begin{split}
&-\Delta v \geq 0 \quad &\mbox{ in } \Omega,\\
&\frac{\partial v}{\partial \nu} +d(x)v\geq 0 &\mbox{ on }\partial\Omega,
\end{split}\right.\end{equation}
for some bounded function  $d$ satisfying $d(x)\geq \tau$ for all $x\in \mathbb R$ and some $\tau>0$. Then $v>0$ in $\overline{\Omega}$ unless $v\equiv 0$.

\label{cor-Moser}{\bf ($L^\infty$ bound when $g$ is bounded).}
Let $w\in H^{\frac{1}{2}}(\mathbb R)$ be a weak solution of \eqref{weak-equation} with non-vanishing right hand side $g$.
If there exists $p_0>1$ such that
\begin{equation}\label{eq::904}
\norm{g}_{L^p(\mathbb R)}\leq c \quad \mbox{for all}\quad p\ge p_0
\end{equation}
(with $c$ independent on $p$), then $w$ is bounded.

We set $H_0$ to be the subspace in $H$ consisting of functions whose trace is orthogonal to $\phi'$ in $L^2(\partial\Omega)$, i.e,
\begin{equation}\label{space}
H_0:=\left\{ u\in H : \int_{\partial\Omega} u\phi'=0\right\}.
\end{equation}

we define the bilinear functional
\begin{equation}\label{bilinear-functional}
B(u,v):=\int_\Omega \nabla u \cdot\nabla v+\int_{\partial\Omega} W''(\phi)uv,\end{equation}
whose associated quadratic form is precisely
$$Q(u)=\int_\Omega|\nabla u|^2+\int_{\partial\Omega}W''(\phi)u^2,\quad u\in H.$$
It is easy to check that $B$ is a continuous and symmetric bilinear functional in $H$.

\label{lem:1}{\bf (Lower bound for $Q$).}
There is some constant $C_0>0$ such that for all $u\in H_0$, where $H_0$ is defined in \eqref{space}, we have that
$$Q(u)\geq C_0\int_{\partial\Omega} u^2.$$

\label{cor-coercivity} {\bf (Coercivity).}
There exists some $C>0$ such that for all $u\in H_0$,
$$B(u,u)\geq C\norm{u}_H^2.$$

It easily follows from Lemma \ref{lem:1}. Indeed,
\begin{equation*}
\begin{split}
B(u,u) & =\int_\Omega \abs{\nabla u}^2+\int_{\partial\Omega}W''(\phi)u^2\geq (1-\mu) C_0 \int_{\partial\Omega} u^2+\mu Q(u)\\
& \geq \mu\int_\Omega \abs{\nabla u}^2+\int_{\partial\Omega} u^2\left[(1-\mu)C_0+\mu W''(\phi)\right].\\
\end{split}\end{equation*}
Because $W''$ is bounded, there exists $\mu>0$ small enough such that $(1-\mu)C_0+\mu W''(\phi)>\tfrac{C_0}{2}$. Therefore,
\begin{equation}\label{eq::909}
B(u,u)\geq\min\left\{\mu,\tfrac{C_0}{2}\right\} \norm{u}_H^2,
\end{equation}
as claimed.

